# Script tự động hóa MCPretentious cho iTerm2

```javascript
const MCPretentious = require('mcp-retentious');

// Khởi tạo MCPretentious với iTerm2 và tmux
const mcp = new MCPretentious({
  terminal: 'iTerm2',
  tmux: true,
  logLevel: 'debug'
});

// Kết nối với môi trường Node.js
mcp.connect('production-node-env').then(() => {
  // Thực thi lệnh trong một session tmux mới
  mcp.execute('npm run build', {
    sessionName: 'build-session',
    onOutput: (output) => {
      console.log(`Build output: ${output}`);
    },
    onError: (error) => {
      console.error(`Build error: ${error}`);
    }
  });
}).catch((error) => {
  console.error(`Connection error: ${error}`);
});
```
